-- FIN-08 Doppio slalom, tiro e 1v1 (insert o aggiornamento)
insert into public.exercises (id, data, updated_at) values ('5eed0000-0000-4000-8000-00000000013d', '{"code":"FIN-08","title":"Finishing & 1v1 – Doppio slalom, tiro e 1v1","area":"finalizzazione","fase":["centrale"],"obiettivi":["conduzione","cambi di direzione","tiro","dribbling","marcatura","transizione"],"eta":"U9-U12","giocatori":"2 file con palla (coni e paletti) + portiere","spazio":"Metà campo con porta","durata":12,"materiale":"4 coni arancioni, 5 paletti rossi, 1 manichino, porta, 1 pallone a testa","perche":"Conduzione in slalom e cambio di direzione sul manichino, tiro dopo lo slalom, poi transizione immediata: chi ha appena tirato diventa difensore e affronta il 1v1. Finalizzazione sotto pressione.","descrizione":"Setup: fila 1 (con palla) sui 4 coni arancioni a sinistra, in slalom; fila 2 (con palla) dietro i 5 paletti rossi sul lato destro, in diagonale; manichino al centro vicino al cerchio di centrocampo; portiere in porta.\nEsecuzione: partono insieme. 1 fa lo slalom tra i coni con palla, 2 fa lo slalom tra i paletti con palla. 2 esce dallo slalom e tira in porta; intanto 1 aggira il manichino e attacca la porta. Dopo il tiro 2 diventa difensore e chiude su 1: 1v1 sul limite dell’area, 1 cerca di superarlo e conclude.\nRitmo continuo, recupero = rotazione in fila.","rotazione":"1: dopo la conclusione torna in fondo alla fila dei coni. 2: dopo il 1v1 torna in fondo alla fila dei paletti. Al giro successivo partono i primi delle due file.","varianti":"Tocchi limitati dopo il manichino. Tiro solo in area o anche da fuori. 2 difende al 100% o al 50%. Tempo massimo di conclusione 3–4″.","coaching":"Slalom: palla vicina, tocchi piccoli con interno ed esterno, testa alta in uscita. 1: cambio di direzione stretto sul manichino, poi velocità verso la porta e lettura del difensore che arriva. 2: tiro preciso in uscita dallo slalom, poi subito transizione e chiusura sul lato forte di 1.","fonte":"Video drill (inviato da Andrea, 23/10/2026)","diagram":{"field":{"preset":"metacampo","w":36,"h":36},"steps":[{"title":"Doppio slalom","note":"1 tra i coni, 2 tra i paletti, entrambi con palla"},{"title":"Tiro di 2","note":"2 tira in porta, 1 aggira il manichino"},{"title":"1v1","note":"2 diventa difensore e chiude su 1"},{"title":"Dribbling","note":"1 supera 2"},{"title":"Conclusione di 1","note":""},{"title":"Fine"}],"items":[{"id":"it1073","type":"gk","pos":{"0":{"x":35,"y":18}}},{"id":"it1074","type":"cone","pos":{"0":{"x":4.5,"y":7}}},{"id":"it1075","type":"cone","pos":{"0":{"x":5.5,"y":9.5}}},{"id":"it1076","type":"cone","pos":{"0":{"x":6.5,"y":12}}},{"id":"it1077","type":"cone","pos":{"0":{"x":7.5,"y":14.5}}},{"id":"it1078","type":"pole","pos":{"0":{"x":10,"y":31}}},{"id":"it1079","type":"pole","pos":{"0":{"x":12,"y":29.5}}},{"id":"it1080","type":"pole","pos":{"0":{"x":14,"y":28}}},{"id":"it1081","type":"pole","pos":{"0":{"x":16,"y":26.5}}},{"id":"it1082","type":"pole","pos":{"0":{"x":18,"y":25}}},{"id":"it1083","type":"mannequin","pos":{"0":{"x":10,"y":19.5}}},{"id":"it1084","type":"playerA","label":"1","pos":{"0":{"x":3.5,"y":4},"1":{"x":8.5,"y":16},"2":{"x":13,"y":21},"3":{"x":21,"y":16},"4":{"x":25.5,"y":13.5}}},{"id":"it1085","type":"playerA","label":"1","pos":{"0":{"x":1.5,"y":1.5}}},{"id":"it1086","type":"playerA","label":"1","pos":{"0":{"x":5.5,"y":1.5}}},{"id":"it1087","type":"playerB","label":"2","pos":{"0":{"x":8,"y":33},"1":{"x":19.5,"y":24},"3":{"x":23.5,"y":18.5},"4":{"x":24.5,"y":15.8}}},{"id":"it1088","type":"playerB","label":"2","pos":{"0":{"x":6.2,"y":34.6}}},{"id":"it1089","type":"playerB","label":"2","pos":{"0":{"x":4.4,"y":35.2}}},{"id":"it1090","type":"ball","pos":{"0":{"x":4.1,"y":4.4},"1":{"x":9.1,"y":16.4},"2":{"x":13.6,"y":21.4},"3":{"x":21.6,"y":16.4},"4":{"x":26.1,"y":13.9},"5":{"x":35.6,"y":17}}},{"id":"it1091","type":"ball","pos":{"0":{"x":8.6,"y":33.4},"1":{"x":20.1,"y":24.4},"2":{"x":35.6,"y":20}}}],"arrows":[{"id":"ar1092","kind":"dribble","step":0,"from":{"x":3.5,"y":4},"to":{"x":8.5,"y":16},"curve":1},{"id":"ar1093","kind":"dribble","step":0,"from":{"x":8,"y":33},"to":{"x":19.5,"y":24},"curve":1.2},{"id":"ar1094","kind":"shot","step":1,"from":{"x":20.1,"y":24.4},"to":{"x":35.6,"y":20}},{"id":"ar1095","kind":"dribble","step":1,"from":{"x":8.5,"y":16},"to":{"x":13,"y":21},"curve":-2.5},{"id":"ar1096","kind":"dribble","step":2,"from":{"x":13,"y":21},"to":{"x":21,"y":16}},{"id":"ar1097","kind":"run","step":2,"from":{"x":19.5,"y":24},"to":{"x":23.5,"y":18.5}},{"id":"ar1098","kind":"dribble","step":3,"from":{"x":21,"y":16},"to":{"x":25.5,"y":13.5},"curve":-1},{"id":"ar1099","kind":"run","step":3,"from":{"x":23.5,"y":18.5},"to":{"x":24.5,"y":15.8}},{"id":"ar1100","kind":"shot","step":4,"from":{"x":26.1,"y":13.9},"to":{"x":35.6,"y":17}}]},"id":"5eed0000-0000-4000-8000-00000000013d","updatedAt":"2026-10-01T00:00:00.000Z"}'::jsonb, now()) on conflict (id) do update set data = excluded.data, updated_at = now();
